import * as THREE from './vendor/three.module.js';
const $=s=>document.querySelector(s),canvas=$('#game'),renderer=new THREE.WebGLRenderer({canvas,antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.setClearColor('#91ccdc');
const scene=new THREE.Scene();scene.fog=new THREE.Fog('#a8d5dd',38,110);
const camera=new THREE.PerspectiveCamera(53,1,.1,160);camera.position.set(0,5.5,9);camera.lookAt(0,1,-12);
scene.add(new THREE.HemisphereLight('#ffffff','#b3a487',2.3));const sun=new THREE.DirectionalLight('#fff4dc',2.1);sun.position.set(-8,20,10);scene.add(sun);
const ground=new THREE.Mesh(new THREE.PlaneGeometry(180,260),new THREE.MeshLambertMaterial({color:'#9b987d'}));ground.rotation.x=-Math.PI/2;ground.position.z=-80;ground.position.y=-1;scene.add(ground);
const world=new THREE.Group();scene.add(world);const player=new THREE.Group();scene.add(player);
let ready=false,running=false,score=0,coins=0,lane=0,jumpY=0,vy=0,slideLeft=0,time=0,distance=0,spawnDistance=15,lastTime=performance.now(),resources=[],objects=[],scenery=[],patterns=0;
let mixer=null,animationActions={},activeAction=null;
const bgm=new Audio('assets/audio/4_1468199407134043205_music_luoyang_music_luoyang.m4a'),crash=new Audio('assets/audio/4_5701420766982499548_Hr_H_crash_Hr_H_crash.m4a');bgm.loop=true;bgm.volume=.24;crash.volume=.35;let muted=false;$('#sound').onclick=()=>{muted=!muted;bgm.muted=crash.muted=muted;$('#sound').setAttribute('aria-pressed',String(muted));$('#sound').textContent=muted?'声音：关':'声音：开';};
const prototypes={},textureLoader=new THREE.TextureLoader();
Object.defineProperty(window,'gameDebug',{get:()=>Object.freeze({ready,running,score,coins,lane,jumpY,sliding:slideLeft>0,distance,resources:[...resources],originalClipCount:Object.keys(animationActions).length,audio:{bgmReady:bgm.readyState>=2,crashReady:crash.readyState>=2,playing:!bgm.paused,muted},animation:activeAction?.getClip().name,obstacles:objects.filter(o=>o.kind!=='coin').map(o=>({lane:o.lane,z:o.mesh.position.z,kind:o.kind})),playerPosition:player.position.toArray()})});
async function json(url){const r=await fetch(url);if(!r.ok)throw new Error(`${url}: HTTP ${r.status}`);return r.json();}
async function model(item){const d=await json('assets/'+item.mesh);if(item.name==='currency_coin'){const keep=[];for(let i=0;i<d.indices.length;i+=3){const tri=d.indices.slice(i,i+3);if(tri.every(v=>d.positions[v*3+1]>-5))keep.push(...tri);}d.indices=keep;for(let i=1;i<d.positions.length;i+=3)if(d.positions[i]<-5)d.positions[i]=0;}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(d.positions,3));if(d.normals?.length===d.positions.length)g.setAttribute('normal',new THREE.Float32BufferAttribute(d.normals,3));if(d.uvs?.length)g.setAttribute('uv',new THREE.Float32BufferAttribute(d.uvs,2));g.setIndex(d.indices);if(!d.normals?.length)g.computeVertexNormals();
 let map=null;if(item.texture){map=await textureLoader.loadAsync('assets/'+item.texture);map.colorSpace=THREE.SRGBColorSpace;map.flipY=item.flipY??true;}
 let material=new THREE.MeshLambertMaterial({map,color:map?'#ffffff':item.color||'#d9c4a0',side:THREE.DoubleSide});if(item.materials){material=await Promise.all(item.materials.map(async spec=>{let tex=null;if(spec.texture){tex=await textureLoader.loadAsync('assets/'+spec.texture);tex.colorSpace=THREE.SRGBColorSpace;tex.flipY=item.flipY??true;}return new THREE.MeshLambertMaterial({map:tex,color:spec.color||'#ffffff',side:THREE.DoubleSide});}));for(const group of d.groups||[])g.addGroup(group.start,group.count,Math.min(group.materialIndex,material.length-1));if(!g.groups.length)g.addGroup(0,d.indices.length,0);}if(item.name==='jake_Mesh'){
 const sk=await json('assets/jake-skeleton.json'),clips=await json('assets/jake-clips.json');
 g.setAttribute('skinIndex',new THREE.Uint16BufferAttribute(sk.skinIndices,4));g.setAttribute('skinWeight',new THREE.Float32BufferAttribute(sk.skinWeights,4));
 const bones=sk.bones.map(b=>{const o=new THREE.Bone();o.name=b.name;o.position.fromArray(b.position);o.quaternion.fromArray(b.quaternion);o.scale.fromArray(b.scale);return o;});
 const rig=new THREE.Group();bones.forEach((b,i)=>{const parent=sk.bones[i].parent;if(parent>=0)bones[parent].add(b);else rig.add(b);});
 const sm=new THREE.SkinnedMesh(g,material);rig.add(sm);rig.updateMatrixWorld(true);sm.bind(new THREE.Skeleton(sk.boneOrder.map(i=>bones[i]),sk.bindPoses.map(a=>new THREE.Matrix4().fromArray(a))),new THREE.Matrix4());sm.frustumCulled=false;
 const root=new THREE.Group();root.add(rig);rig.scale.set(-.188,.188,.188);rig.rotation.y=Math.PI;
 mixer=new THREE.AnimationMixer(rig);for(const data of clips){const clip=THREE.AnimationClip.parse(data);clip.uuid=THREE.MathUtils.generateUUID();animationActions[clip.name]=mixer.clipAction(clip);}playAnimation('run');resources.push(item.name+' + 原骨架/跑步/跳跃/滑行动画');return root;
 }const m=new THREE.Mesh(g,material);m.scale.x=item.mirror===false?1:-1;const root=new THREE.Group();root.add(m);if(item.rotation)m.rotation.set(...item.rotation);root.updateMatrixWorld(true);const b=new THREE.Box3().setFromObject(root),size=b.getSize(new THREE.Vector3());const s=item.height?item.height/size.y:item.width?item.width/size.x:1;root.scale.setScalar(s);m.position.set(-(b.min.x+b.max.x)/2,-b.min.y,-(b.min.z+b.max.z)/2);root.userData.source=item.name;resources.push(item.name);return root;}
function playAnimation(name){const a=animationActions[name]||animationActions.run;if(!a||a===activeAction)return;if(activeAction)activeAction.fadeOut(.12);a.reset().fadeIn(.12).play();activeAction=a;}
function clone(name){return prototypes[name].clone(true);}
function addEnvironment(){
 for(let z=20;z>-220;z-=40){const floor=clone('ground');floor.position.set(0,-.3,z);world.add(floor);scenery.push({mesh:floor,loop:240,retireAt:40});}
 const railLength=17.647;for(let z=8;z>-130;z-=railLength){for(let l=-1;l<=1;l++){const t=clone('track');t.position.set(l*2.7,-.23,z);world.add(t);scenery.push({mesh:t,loop:railLength*8});}}
 for(let z=0;z>-126;z-=18){for(const side of [-1,1]){const b=clone('building');b.position.set(side*9,-.3,z);b.rotation.y=side<0?Math.PI:0;world.add(b);scenery.push({mesh:b,loop:126});}}
}
function put(kind,l,z){let mesh=clone(kind);mesh.position.set(l*2.7,kind==='coin'?1.1:0,z);if(kind==='coin')mesh.rotation.y=Math.PI/2;world.add(mesh);objects.push({mesh,kind,lane:l});}
function row(z){const p=patterns++;const blocked=[0,-1,1,-1,0,1][p%6],kind=p%4===1&&prototypes.barrier?'barrier':p%4===2&&prototypes.overhead?'overhead':'train';put(kind,blocked,z);const safe=blocked===0?1:0;for(let i=0;i<5;i++)put('coin',safe,z+3+i*2);}
function start(){bgm.currentTime=0;bgm.play().catch(()=>{});objects.forEach(o=>world.remove(o.mesh));objects=[];running=true;score=coins=distance=time=0;lane=jumpY=vy=slideLeft=0;patterns=0;spawnDistance=15;player.position.set(0,0,0);player.scale.set(1,1,1);for(let z=-28;z>-110;z-=25)row(z);$('#overlay').classList.add('hidden');$('#overlay').classList.remove('result');$('#run-result').hidden=true;$('#hint').textContent='← → 换道 · ↑ 跳跃 · ↓ 滑行';}
function finish(){running=false;bgm.pause();crash.currentTime=0;crash.play().catch(()=>{});$('#overlay').classList.add('result');$('#title').textContent='本次成绩';$('#description').textContent='调整路线，再挑战一次！';$('#run-result').hidden=false;$('#result-distance').textContent=Math.floor(distance);$('#result-coins').textContent=coins;$('#start').textContent='重新出发';$('#overlay').classList.remove('hidden');}
function action(a){if(!running)return;if(a==='left')lane=Math.max(-1,lane-1);if(a==='right')lane=Math.min(1,lane+1);if(a==='jump'&&jumpY===0){vy=9;slideLeft=0;}if(a==='slide'&&jumpY<.1)slideLeft=.85;}
document.addEventListener('keydown',e=>{const actions={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'jump',' ':'jump',w:'jump',W:'jump',ArrowDown:'slide',s:'slide',S:'slide'};if(actions[e.key]){e.preventDefault();action(actions[e.key]);}if(e.key==='Enter'&&ready&&!running)start();});
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();action(b.dataset.action);}));let pointer=null;canvas.addEventListener('pointerdown',e=>pointer={x:e.clientX,y:e.clientY});canvas.addEventListener('pointerup',e=>{if(!pointer)return;const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;pointer=null;if(Math.max(Math.abs(dx),Math.abs(dy))<20)return;action(Math.abs(dx)>Math.abs(dy)?dx>0?'right':'left':dy>0?'slide':'jump');});$('#start').onclick=start;
function update(dt){if(!running)return;time+=dt;playAnimation(slideLeft>0?'roll':jumpY>0?'jump':'run');if(mixer)mixer.update(dt);const speed=Math.min(25,10+distance/250),dz=speed*dt;distance+=dz;score=Math.floor(distance)+coins*10;player.position.x=THREE.MathUtils.damp(player.position.x,lane*2.7,14,dt);if(jumpY>0||vy>0){vy-=22*dt;jumpY=Math.max(0,jumpY+vy*dt);if(jumpY===0)vy=0;}slideLeft=Math.max(0,slideLeft-dt);player.scale.y=1;player.position.y=jumpY+(jumpY===0&&slideLeft===0?Math.abs(Math.sin(time*13))*.07:0);player.rotation.z=Math.sin(time*13)*.025;player.rotation.y=-(lane*2.7-player.position.x)*.1;
 for(const s of scenery){s.mesh.position.z+=dz;if(s.mesh.position.z>(s.retireAt??15))s.mesh.position.z-=s.loop;}
 for(const o of objects){o.mesh.position.z+=dz;if(o.kind==='coin')o.mesh.rotation.y+=dt*3;if(Math.abs(o.mesh.position.z)<(o.kind==='train'?2.9:.8)&&Math.abs(player.position.x-o.lane*2.7)<.8){if(o.kind==='coin'){if(jumpY<1.8){coins++;world.remove(o.mesh);o.remove=true;}}else if(o.kind==='barrier'?jumpY<1:o.kind==='overhead'?slideLeft===0:true){finish();break;}}if(o.mesh.position.z>15){world.remove(o.mesh);o.remove=true;}}
 objects=objects.filter(o=>!o.remove);if(distance>=spawnDistance){row(-100);spawnDistance+=25;}$('#score').textContent=Math.floor(distance)+' m';$('#coins').textContent=coins;
}
function frame(now){const dt=Math.min(.04,(now-lastTime)/1000);lastTime=now;const w=innerWidth,h=innerHeight;if(canvas.width!==Math.round(w*renderer.getPixelRatio())||canvas.height!==Math.round(h*renderer.getPixelRatio())){renderer.setSize(w,h,false);camera.aspect=w/h;camera.fov=w/h<.8?65:53;camera.updateProjectionMatrix();}update(dt);renderer.render(scene,camera);requestAnimationFrame(frame);}requestAnimationFrame(frame);
try{const config=await json('assets/game-assets.json');for(const [key,item] of Object.entries(config)){if(!item.mesh)continue;$('#load').textContent='正在载入：'+item.name;prototypes[key]=await model(item);}if(!prototypes.player||!prototypes.train||!prototypes.coin)throw new Error('必需的原始主角、列车或金币模型缺失');player.add(prototypes.player);addEnvironment();ready=true;$('#load').textContent='';$('#asset-note').textContent='原始 Jake / 列车 / 金币资源 · Three.js 学习适配';$('#start').disabled=false;$('#start').textContent='开始奔跑';}catch(e){console.error(e);$('#load').textContent='加载失败：'+e.message;$('#start').textContent='资源未就绪';$('#asset-note').textContent='请检查本地资源或刷新页面，未使用替代模型。';}

